/bin/bash -lc "node --input-type=commonjs <<'NODE'
const assert = require('node:assert/strict')
const fs = require('node:fs')
const ts = require('typescript')
const { NextRequest } = require('next/server')
const source = fs.readFileSync('middleware.ts', 'utf8')
const compiled = ts.transpileModule(source, {
  compilerOptions: { module: ts.ModuleKind.CommonJS },
}).outputText
const middlewareModule = { exports: {} }
new Function('require', 'module', 'exports', compiled)(require, middlewareModule, middlewareModule.exports)
const { middleware } = middlewareModule.exports
const originalLog = console.log
const logs = []
console.log = (...args) => logs.push(args)
try {
  const paths = ['/', '/api/example', '/_next/static/example.js', '/missing']
  const responses = paths.map((path) => middleware(new NextRequest("'`https://example.com${path}?query=ignored`)))
  const ids = responses.map((response) => response.headers.get('"'X-Request-Id'))
  for (const id of ids) {
    assert.match(id, /"'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i)
  }
  assert.equal(new Set(ids).size, ids.length)
  assert.deepEqual(logs, paths.map((path) => [path]))
  for (const response of responses) {
    assert.equal(response.headers.get('"'x-middleware-next'), '1')
  }
} finally {
  console.log = originalLog
}
console.log('Middleware checks passed: unique UUID headers, pathname logs, and request continuation.')
NODE"
